import {formatCoins,currencyUnit,coin} from './economy.js';
import {TEST_PREPARATIONS,testStorage,createTestCheckpoint,advanceTestIdle} from './test-mode.js';
import {canCollectMuseum,idleCollectionRemaining,freshPlayer,buyArmory,armoryUpgrade,skillRank,skillEffect,skillUpgrade,potionCost,DODGE_TIMING,PRACTICE_KINDS,trainingMission,checkpointTraining,GROUNDS,STATS,ITEMS,ARMORY_SETS,SKILLS,CAMPAIGN_STAGES,BATTLES_PER_STAGE,TOTAL_BATTLES,TRAINING_UPGRADE_REQUIREMENTS,readSave,writeSave,xpNeeded,combatStats,trainingCost,buyItem,upgradeGround,learnSkill,allocateStat,settleTraining,settleBattle,legacyCost,collectMuseum,upgradeLegacy,purchasePotion} from './core.js';
import {drawWorld,enemy,menuIllustration,FULL_BODY_ATTACK_ART,FULL_BODY_JUMP_ART,TOWN_ART,ARENA_BATTLE_ART,townPlacement} from './art.js';
import {equippedHero as hero,townHero} from './hero-art.js';
import {idlePortrait} from './portrait-art.js';
import {rigPreview,rigPortrait,hasRigEquipment,equipmentIllustration} from './rig-art.js';
import {Training} from './training.js';
import {placeStrengthControls} from './strength-layout.js';
import {Battle} from './battle.js';
import {setupMobile} from './mobile.js';
const $=s=>document.querySelector(s),screen=$('#screen'),canvas=$('#world'),ctx=canvas.getContext('2d'),dialog=$('#dialog');
let storage;try{storage=window.localStorage}catch{storage={getItem(){throw Error('Storage unavailable')},setItem(){throw Error('Storage unavailable')}}}
let testing=new URL(location.href).searchParams.get('test')==='1',gameStorage=testing?testStorage(storage):storage;
const loaded=readSave(gameStorage);let player=loaded.player,view='town',selectedStage=Math.min(player.stage,TOTAL_BATTLES),session=null,paused=false,lastTime=0,toastTimer=0,townArrivalTimer=0,audio=null,saveWarning=false,returnFocus=null;
let allocationCount='1',testBattle=Math.min(player.stage,TOTAL_BATTLES),testPreparation='ready';
let arenaPage=Math.floor((selectedStage-1)/BATTLES_PER_STAGE);
const mobile=setupMobile(()=>{const status=$('#offline-status');if(status)status.textContent=mobile.status;const update=$('#install-update');if(update)update.hidden=!mobile.updateReady;const check=$('#check-update');if(check)check.disabled=mobile.checking});
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>Math.round(n*100)+'%';
const rigMotion=window.matchMedia('(prefers-reduced-motion: reduce)'),rigPoses=[['standing','Standing'],['raised','Raised arm'],['attack','Attack'],['airborne','Airborne'],['landing','Landing']];
const equipmentSlots=[['armor','Armor set'],['weapon','Weapon'],['shield','Shield']];
let rigState={pose:'standing',playing:true,animated:true,time:0,...player.equipment};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function save(){const ok=writeSave(gameStorage,player);if(!ok&&!saveWarning){saveWarning=true;toast('Saving is unavailable in this browser. Keep this tab open.')}updateWallet();return ok}
function sound(kind){if(!player.settings.sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';const f=({hit:640,heal:440,block:360,star:880,miss:160})[kind]||640;osc.frequency.setValueAtTime(f,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(kind==='miss'?65:kind==='block'?210:f*1.5,audio.currentTime+.09);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.12);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.13)}catch{}}
function modal(html){dialog.classList.toggle('strength-dialog',session?.streak);dialog.classList.remove('economy-test-dialog','battle-result-dialog');returnFocus=document.activeElement;dialog.innerHTML=html;if(!dialog.open)dialog.showModal()}
function runInProgress(){return Boolean(session&&(!session.done||view==='battle'&&!session.resultShown))}
function closeModal(){dialog.close();returnFocus?.focus?.();if(runInProgress())paused=document.hidden||window.innerHeight>window.innerWidth}
function header(title){$('#app').classList.toggle('test-mode',testing);let indicator=$('#test-indicator');if(!indicator){indicator=document.createElement('div');indicator.id='test-indicator';indicator.textContent='TEST SAVE';indicator.setAttribute('role','status');$('#app').append(indicator)}indicator.hidden=!testing;canvas.setAttribute('aria-label',view==='arena'?'Arena hall':view==='town'||view==='home'?'Sky-island town':view==='battle'?'Arena battlefield':'Training grounds');$('#app').classList.toggle('home-screen',view==='town');$('#app').classList.toggle('title-screen',view==='home');$('#home-button').hidden=view!=='town';$('#app').classList.toggle('arena-screen',view==='arena');$('#app').classList.toggle('gameplay-screen',view==='battle');$('#app').classList.toggle('menu-screen',['train','forge','hero','legacy','hero-rig'].includes(view));$('#location').textContent=title;updateWallet()}
function updateWallet(){const el=$('#coins'),unit=currencyUnit(player.coins);el.textContent=formatCoins(player.coins,false);el.setAttribute('aria-label',formatCoins(player.coins));el.title=player.coins.toString()+' gold equivalent';$('header .wallet').dataset.currency=unit.name.toLowerCase()}
function gold(amount,id=''){return `<span class="gold-amount" data-currency="${currencyUnit(amount).name.toLowerCase()}" aria-label="${formatCoins(amount)}" title="${coin(amount)} gold equivalent">${$('header .wallet .coin').outerHTML}<b${id?` id="${id}"`:''}>${formatCoins(amount,false)}</b></span>`}
function miniButton(label,attributes,soft=false){return `<button class="mini-button${soft?' soft':''}" ${attributes}><span>${label}</span></button>`}
function destination(title,kind,body){header(title);screen.innerHTML=`<section class="destination-menu ${kind}-menu" aria-label="${title}"><button class="arena-town" data-go="town"><span>← Town</span></button><div class="destination-body">${body}</div></section>`;screen.querySelectorAll('canvas[data-illustration]').forEach(c=>{if(!ITEMS[c.dataset.illustration])menuIllustration(c.getContext('2d'),c.width,c.height,c.dataset.illustration)});drawEquipmentIllustrations()}
function illustration(kind,label,css=''){return `<canvas class="menu-illustration ${css}" width="300" height="240" data-illustration="${kind}" role="img" aria-label="${label}"></canvas>`}
function profile(compact=false){const stats=combatStats(player);return `<div class="menu-profile"><canvas data-hero="idle" width="400" height="340" aria-label="Your equipped adventurer"></canvas>${compact?`<div class="profile-combat"><span>${stats.attack} ATK</span><span>${stats.hp} HP</span></div>`:`<div class="profile-name"><h2>${escape(player.name)}</h2>${miniButton('✎','data-action="appearance" aria-label="Edit name and scarf"',true)}</div><div class="profile-level">Lv. ${player.level}</div><span class="hero-xp"><progress max="${xpNeeded(player)}" value="${player.xp}" aria-label="Hero experience"></progress><span>${player.xp} / ${xpNeeded(player)} XP</span></span><div class="profile-combat"><span>${stats.attack} ATK</span><span>${stats.hp} HP</span></div>`}</div>`}

function placeTownTargets(){
if(view!=='town')return;
const {width,height}=canvas.getBoundingClientRect(),fit=townPlacement(width,height);
for(const point of TOWN_ART.destinations){const button=screen.querySelector(`[data-town-destination="${point.id}"]`);if(button){button.style.setProperty('--town-x',`${fit.x+point.x*fit.scale}px`);button.style.setProperty('--town-y',`${fit.y+point.y*fit.scale}px`)}}
const target=screen.querySelector('[data-town-hero]');
if(target){target.style.setProperty('--town-x',`${fit.x+TOWN_ART.hero.x*fit.scale}px`);target.style.setProperty('--town-y',`${fit.y+(TOWN_ART.hero.y-TOWN_ART.hero.height)*fit.scale}px`);target.style.setProperty('--town-hero-height',`${TOWN_ART.hero.height*fit.scale}px`)}
}
function levelProgress(){return `<div class="town-progress" aria-label="Level ${player.level}"><span class="town-level-badge" aria-label="Level ${player.level}">${player.level}</span><span class="town-xp-track"><progress max="${xpNeeded(player)}" value="${player.xp}" aria-label="Experience to next level" aria-valuetext="${player.xp} of ${xpNeeded(player)} XP"></progress><span class="town-xp-value" aria-hidden="true">${player.xp} / ${xpNeeded(player)} XP</span></span></div>`}
function town(){header(TOWN_ART.name);screen.innerHTML=`<h1 class="town-arrival" role="status" data-motion="${player.settings.motion&&!rigMotion.matches}">${escape(TOWN_ART.name)}</h1>${TOWN_ART.destinations.map(point=>`<button data-go="${point.id}" data-town-destination="${point.id}" class="map-pin town-destination" aria-label="${point.label}"><span class="map-label">${point.label}</span></button>`).join('')}<button class="map-pin town-hero-target" data-go="hero" data-town-hero aria-label="Hero — view your adventurer"><span class="map-label">Hero</span></button>${levelProgress()}`;placeTownTargets();const arrival=screen.querySelector('.town-arrival');clearTimeout(townArrivalTimer);townArrivalTimer=setTimeout(()=>{arrival.remove();townArrivalTimer=0},3200)}
function homeMenu(){header('Home');screen.innerHTML=`<section class="title-menu" aria-label="Home"><div class="title-panel"><h1>One Brave<br>Odyssey</h1><div class="title-actions"><button class="primary" data-go="town">Play Game</button><button class="secondary" disabled>Credits <small>Soon</small></button><button class="secondary" disabled>Achievements <small>Soon</small></button></div></div></section>`}

function trainMenu(){destination('Training','training',`<div class="training-stations">${GROUNDS.map(g=>{const level=player.trainingLevels[g.id],required=TRAINING_UPGRADE_REQUIREMENTS[level]||0,locked=player.cleared.length<required,maxed=level>=5,cost=trainingCost(player,g.id);return `<article class="training-station">${illustration(g.id,g.name+' practice')}<div class="station-info"><div class="station-heading"><h2>${g.name}</h2><b style="color:${g.color}" aria-label="${g.name} stat ${player.stats[g.id]}">${player.stats[g.id]}</b></div><div class="station-level">Lv. ${level}${g.id==='accuracy'?' · 60s':''} <span>×${(1+.25*(level-1)).toFixed(2)}</span></div><div class="station-actions">${miniButton('Train',`data-train="${g.id}" aria-label="Train ${g.name}. ${g.description}"`)}${miniButton(maxed?'Max':locked?'Battle '+required:'↑ '+gold(cost),`data-upgrade="${g.id}" aria-label="Upgrade ${g.name} training: +25% yield. ${locked?'Clear battle '+required:formatCoins(cost)}" ${maxed||locked||player.coins<cost?'disabled':''}`,true)}</div></div></article>`}).join('')}</div>`)}
function arenaMenu(){
header('Arena');
const stage=CAMPAIGN_STAGES[arenaPage],comingSoon=stage.comingSoon,unlocked=!comingSoon&&selectedStage<=TOTAL_BATTLES&&selectedStage<=player.stage;
const choices=comingSoon?'':Array.from({length:BATTLES_PER_STAGE},(_,i)=>stage.firstBattle+i).map(number=>`<button class="arena-stage ${selectedStage===number?'selected ':''}${player.cleared.includes(number)?'cleared':''}" data-stage="${number}" aria-label="Battle ${number}${number>player.stage?', locked':player.cleared.includes(number)?', cleared':''}" aria-pressed="${selectedStage===number}" ${number>player.stage?'disabled':''}><span>${number}${number>player.stage?'<svg viewBox="0 0 12 14" aria-hidden="true"><path d="M3 6V4a3 3 0 0 1 6 0v2M2 6h8v7H2Z" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round"/></svg>':player.cleared.includes(number)?'<i aria-hidden="true">✓</i>':''}</span></button>`).join('');
screen.innerHTML=`<section class="arena-menu" aria-label="Arena battle selection"><button class="arena-town" data-go="town" aria-label="Back to Town"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 12H4m7-7-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><section class="arena-stage-panel" aria-label="Choose a battle"><div class="arena-stage-heading"><button class="arena-page-arrow" data-arena-page="${arenaPage-1}" aria-label="Previous stage" ${arenaPage===0?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><h1 class="arena-page-title" tabindex="-1" aria-live="polite">${stage.label}</h1><button class="arena-page-arrow" data-arena-page="${arenaPage+1}" aria-label="Next stage" ${arenaPage===CAMPAIGN_STAGES.length-1?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 7 7-7 7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button></div>${comingSoon?'<div class="arena-coming-soon" role="status"><span aria-hidden="true">✦</span><p>Coming soon</p></div>':`<div class="arena-encounters" role="group" aria-label="Battles ${stage.firstBattle} to ${stage.lastBattle}">${choices}</div>`}</section><canvas class="arena-portrait arena-adventurer" width="400" height="340" data-hero aria-label="Your adventurer"></canvas>${comingSoon?'':`<canvas class="arena-portrait arena-opponent" width="400" height="340" data-enemy="${(selectedStage-1)%3}" data-scale="2.5" aria-label="Opponent for battle ${selectedStage}"></canvas>`}<div class="arena-entry"><div class="arena-actions"><button class="arena-fight" data-fight="${selectedStage}" aria-label="${comingSoon?'Stage 3 coming soon':unlocked?'Fight battle '+selectedStage:'Battle '+selectedStage+' is locked'}" ${unlocked?'':'disabled'}><span>${comingSoon?'Coming soon':'Fight'}</span></button>${player.survivalUnlocked?'<button class="arena-survival" data-survival="true" aria-label="Endless survival"><span>∞</span></button>':''}</div></div></section>${levelProgress()}`
}
function forge(){const full=armoryUpgrade(player),tonic=potionCost(player),stock=equipmentSlots.map(([slot,label])=>{const current=ITEMS[player.equipment[slot]],next=current.tier<TOTAL_BATTLES?ITEMS[`${slot}_t${current.tier+1}`]:null,shown=next||current,effect=`${current.bonus}%${next?' → '+next.bonus+'%':''} ${slot==='weapon'?'attack':slot==='armor'?'health':'damage reduction'}`;return `<article class="equipment-tile"><div class="equipment-slot">${label}</div><div class="equipment-current">${current.name}</div>${illustration(shown.id,shown.name)}<h2>${next?next.name:'Fully upgraded'}</h2><div class="item-bonus">${effect}</div>${next?miniButton('↑ '+gold(next.cost),`data-item="${next.id}" aria-label="Upgrade ${slot} to ${next.name}. ${formatCoins(next.cost)}" ${player.coins<next.cost?'disabled':''}`):'<div class="equipment-max">✓ Max</div>'}</article>`}).join('');destination('Shop','shop',`<div class="shop-layout">${profile(true)}<div class="shop-stock"><div class="equipment-grid" aria-label="Equipment upgrades">${stock}</div>${full.items.length?miniButton('Upgrade full set · '+gold(full.cost),`data-action="armory-buy" ${player.coins<full.cost?'disabled':''}`):''}<div class="tonic-stock">${illustration('tonic','Skyberry tonic')}<div><b>Tonic <span>${player.potions}/9</span></b><small>+45% HP · 2 uses / battle</small></div>${miniButton(gold(tonic),`data-action="tonic-buy" aria-label="Buy tonic for ${formatCoins(tonic)}" ${player.coins<tonic||player.potions>=9?'disabled':''}`)}</div></div></div>`)}
function skillDescription(key){const rank=skillRank(player,key),effect=skillEffect(player,key),next=rank&&rank<10?skillEffect({...player,skillLevels:{...player.skillLevels,[key]:rank+1}},key):effect,value=(field,digits=0,factor=1)=>{const current=(effect[field]*factor).toFixed(digits),upgraded=(next[field]*factor).toFixed(digits);return current+(current!==upgraded?'→'+upgraded:'')};if(key==='flare')return value('damage',2)+'× damage · '+value('cooldown')+'s';if(key==='bash')return value('damage',2)+'× + stun · '+value('cooldown')+'s';if(key==='poison')return value('tickDamage',2)+'× / sec · '+effect.duration+'s poison';if(key==='ward')return '½ damage · '+value('guardHits')+' hits · '+value('cooldown',1)+'s';return value('heal',0,100)+'% HP · '+value('cooldown')+'s'}
function heroMenu(){const stats=combatStats(player),effects={strength:stats.attack+' ATK',accuracy:pct(stats.hit)+' hit',dodge:pct(stats.dodge)+' evade',block:pct(stats.block)+' guard',crit:pct(stats.crit)+' critical'};destination('Hero','hero',`<div class="hero-layout"><div class="hero-profile-preview">${profile()}${miniButton('Animation preview','data-go="hero-rig"',true)}</div><section class="menu-panel hero-attributes"><div class="panel-heading"><h2>Stats<small class="rating-context">vs battle ${Math.min(player.stage,TOTAL_BATTLES)}</small></h2><span>${player.statPoints} points</span><select class="point-amount" data-stat-amount aria-label="Stat points per tap">${['1','5','all'].map(n=>`<option value="${n}" ${allocationCount===n?'selected':''}>${n==='all'?'All':'+'+n}</option>`).join('')}</select></div>${GROUNDS.map(g=>`<div class="attribute-row"><span class="attribute-icon" style="color:${g.color}" aria-hidden="true">${g.icon}</span><div><b>${g.name}</b><small>${effects[g.id]}</small></div><strong>${player.stats[g.id]}</strong>${miniButton('+',`data-stat="${g.id}" aria-label="Increase ${g.name} using ${allocationCount==='all'?'all available':allocationCount} stat points" ${player.statPoints<1?'disabled':''}`,true)}</div>`).join('')}</section><section class="hero-skills"><div class="panel-heading"><h2>Skills</h2><span>${player.skillPoints} ${player.skillPoints===1?'point':'points'}</span></div>${Object.entries(SKILLS).map(([key,skill])=>{const offer=skillUpgrade(player,key),rank=skillRank(player,key),disabled=offer.maxed||!offer.unlocked||player.skillPoints<offer.points||player.coins<offer.cost,label=offer.maxed?'Max':!offer.unlocked?offer.requirement:(rank?'Upgrade':'Learn')+' · '+offer.points+' SP'+(offer.cost?' · '+formatCoins(offer.cost):'');return `<article class="skill-tile"><span class="skill-symbol" aria-hidden="true">${skill.icon}</span><div><h3>${skill.name} <span>${rank}/10</span></h3><small>${skillDescription(key)}</small></div>${miniButton(label,`data-skill="${key}" aria-label="${skill.name}. ${skillDescription(key)}. ${label}" ${disabled?'disabled':''}`,disabled)}</article>`}).join('')}</section></div>`)}
function heroRigMenu(){const selected=ARMORY_SETS.find(set=>equipmentSlots.every(([slot])=>set.equipment[slot]===rigState[slot]));header('Hero motion');screen.innerHTML=`<section class="destination-menu rig-menu" aria-label="Hero motion preview"><button class="arena-town" data-go="hero"><span>← Hero</span></button><div class="destination-body"><div class="rig-layout"><figure class="rig-figure"><canvas data-rig-preview width="640" height="440" role="img" aria-label="Hero equipment preview, ${rigPoses.find(([key])=>key===rigState.pose)[1].toLowerCase()} pose"></canvas><figcaption><span>Try equipment</span><span data-rig-state role="status">Loading…</span></figcaption></figure><div class="rig-controls"><label class="rig-set-control" for="rig-armory-set">Armory set<select id="rig-armory-set" data-rig-set>${selected?'':'<option value="" selected disabled>Current equipment</option>'}${ARMORY_SETS.map(set=>`<option value="${set.id}" ${selected?.id===set.id?'selected':''}>${set.name}</option>`).join('')}</select></label><div class="rig-pose-controls" role="group" aria-label="Choose a hero pose">${rigPoses.map(([key,label])=>miniButton(label,`data-rig-pose="${key}" aria-pressed="${rigState.pose===key}"`,rigState.pose!==key)).join('')}${miniButton(rigState.playing?'Ⅱ Pause':'▶ Play',`data-action="rig-play" aria-pressed="${rigState.playing}"`,true)}</div><a class="rig-editor-link" href="hero-editor.html">Open hero editor ↗</a></div></div></div></section>`}
function legacy(){destination('Legacy','legacy',`<div class="legacy-layout"><article class="legacy-place">${illustration('home','Windward Lodge')}<h2>Lodge</h2><div class="legacy-level">Lv. ${player.home}/5 <span>+${player.home*10}% replay gold</span></div>${miniButton(player.home>=5?'Max':(player.home?'Upgrade ':'Build ')+gold(legacyCost(player,'home')),`data-legacy="home" aria-label="Improve the lodge: +10% replay gold" ${player.home>=5||player.coins<legacyCost(player,'home')?'disabled':''}`)}</article><article class="legacy-place">${illustration('gallery','Cloudkeeper Gallery')}<h2>Gallery</h2><div class="legacy-level">Lv. ${player.museum}/5 <span>+${player.museum*30}% idle income</span></div><div class="legacy-actions">${miniButton(player.museum>=5?'Max':(player.museum?'Upgrade ':'Build ')+gold(legacyCost(player,'museum')),`data-legacy="museum" aria-label="Improve the gallery: +30% base idle income" ${player.museum>=5||player.coins<legacyCost(player,'museum')?'disabled':''}`)}${miniButton('Collect','id="collect-idle" data-action="collect"',true)}</div></article><section class="menu-panel journal-panel"><h2>Records</h2><dl><div><dt>Arena</dt><dd>${player.cleared.filter(stage=>stage<=TOTAL_BATTLES).length}/${TOTAL_BATTLES}</dd></div><div><dt>Sessions</dt><dd>${player.sessions}</dd></div><div><dt>Hits</dt><dd>${player.totalHits}</dd></div><div><dt>Best combo</dt><dd>×${player.bestCombo}</dd></div></dl></section></div>`);updateCollectButton()}
function updateCollectButton(){const button=$('#collect-idle');if(!button)return;const remaining=idleCollectionRemaining(player),seconds=Math.ceil(remaining/1000),wait=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0'),label=!player.cleared.length?'Clear the first battle to earn idle income':remaining>0?'Collect available in '+wait:canCollectMuseum(player)?'Collect idle resources':'No idle resources to collect yet';button.disabled=!canCollectMuseum(player);if(button.title!==label){button.title=label;button.setAttribute('aria-label',label)}}
function navigate(target,force=false){if(!['town','home','train','arena','forge','hero','legacy','hero-rig'].includes(target))return false;if(runInProgress()&&!force){if(view==='training'&&target==='town')trainingResult();else pauseMenu(target);return false}clearTimeout(townArrivalTimer);townArrivalTimer=0;session=null;paused=false;$('#app').classList.remove('strength-session','block-session','critical-session');screen.classList.remove('training-run','battle-ending');if(target==='hero-rig'&&view!==target)rigState={pose:'standing',playing:true,animated:true,time:0,...player.equipment};view=target;({town,home:homeMenu,train:trainMenu,arena:arenaMenu,forge,hero:heroMenu,legacy,'hero-rig':heroRigMenu})[target]();return true}
function startTraining(kind){if(mobile.applying){toast('Installing the update. Please wait.');return}if(!STATS.includes(kind)||runInProgress())return;view='training';session=new Training(kind,player,sound);session.reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;screen.classList.add('training-run');paused=false;if(session.streak){practiceScreen();updateHud();return}const g=GROUNDS.find(g=>g.id===kind);header(g.name+' training');const instructions={accuracy:'Tap Throw when the sight overlaps the target.'};const buttons=`<span></span><button class="control gold wide" data-input="tap">${{accuracy:'◎ Throw'}[kind]}</button>`;screen.innerHTML=`<div class="training-hud"><div><span class="eyebrow" style="color:#326674">TRAINING GROUNDS</span><h2>${g.name}</h2></div><div class="row"><div class="metric"><b id="time">60</b><small>seconds left</small></div><div class="metric accuracy-goal"><b id="accuracy-points">0 / 16</b><progress id="accuracy-meter" max="16" value="0" aria-label="Points toward the next Accuracy increase"></progress><small id="accuracy-mission"></small></div><div class="metric"><b id="combo">0×</b><small>combo</small></div><button class="back" data-action="pause">Ⅱ Pause</button></div></div><div class="instruction">${instructions[kind]}</div><div class="controls">${buttons}</div>`;updateHud()}
function practiceScreen(){
$('#app').classList.add('strength-session');
const dodge=session.kind==='dodge',block=session.kind==='block',critical=session.kind==='crit',name=GROUNDS.find(g=>g.id===session.kind).name;
$('#app').classList.toggle('block-session',block);$('#app').classList.toggle('critical-session',critical);
header(name+' training');
const tutorial=session.tutorialRemaining>0;
if(tutorial){player.tutorials[session.kind]=true;save()}
const controls=block||critical?[]:dodge?[['high','jump','Jump'],['low','tuck','Tuck'],['kick','back','Back']]:[['high','0','High'],['low','2','Low'],['mid','1','Mid']];
const instructions=critical?'Tap only on HIT! Wait for the second cue. Mistakes reset your combo.':block?'Drag to aim the shield. Block oranges. Let stars through to collect them.':dodge?'Tuck: high. Jump: low. Back: mid. Dodge just before impact for a star.':'High, Mid or Low to slash fruit. Kick for stars. Town banks your rewards.';
screen.innerHTML=`${critical?'<button id="critical-playfield" data-input="hit" aria-label="Critical training play area. Tap only on HIT to jump. Wait for the airborne HIT, then tap for a star. Missed cues or taps without HIT reset the combo."></button>':''}${controls.map(([key,action,label])=>`<button class="strength-action ${key==='kick'?'kick-action':''}" data-layout="${key}" data-input="${action}" aria-label="${label}${dodge?' dodge':' slash'}">${label}</button>`).join('')}<div class="strength-hud"><button class="strength-town" data-go="town" aria-label="Finish practice and show results">← Town</button><div class="training-goal"><span class="goal-track"><span class="goal-well" aria-hidden="true"><i id="goal-fill"></i></span><span class="goal-marker" aria-hidden="true"></span><progress class="sr-only" id="goal-meter" max="4" value="0" aria-label="Points toward the next stat increase"></progress></span><b id="combo" aria-label="Combo multiplier">×1</b></div></div>${dodge||block||critical?'':'<button class="strength-action kick-action" data-layout="kick" data-input="kick" aria-label="Rear kick — strike falling sparks">Kick</button>'}${block?'<div id="block-stick" role="slider" tabindex="0" aria-label="Rotate shield" aria-valuemin="0" aria-valuemax="359" aria-valuenow="0"><span class="block-stick-knob"></span></div>':''}${critical?'<span id="critical-cue-status" class="sr-only" role="status"></span>':''}<aside class="training-mission strength-goal" aria-label="Side mission"><div class="goal-caption"><b id="mission-number"></b><span id="mission-progress"></span></div><div id="mission-title"></div><progress id="mission-meter" max="1" value="0" aria-label="Side mission progress"></progress><span id="mission-message" role="status"></span></aside>${tutorial?`<div id="strength-tutorial" class="strength-tutorial" role="status">${instructions}</div>`:''}<div id="goal-announcement" class="sr-only" role="status"></div>`;placeStrengthControls(screen);if(block)bindBlockStick()
}
function bindBlockStick(){
const pad=$('#block-stick');let pointer=null;
const active=()=>session?.kind==='block'&&!session.done&&!paused;
const aim=angle=>{session.aimShield(angle);const degrees=Math.round((angle*180/Math.PI+360)%360)%360;pad.setAttribute('aria-valuenow',degrees);pad.setAttribute('aria-valuetext',degrees+' degrees')};
const move=e=>{
if(!active())return;
const r=pad.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,distance=Math.hypot(dx,dy),limit=r.width/2-23,scale=Math.min(1,limit/Math.max(1,distance));
pad.style.setProperty('--stick-x',dx*scale+'px');pad.style.setProperty('--stick-y',dy*scale+'px');
if(distance>=7){const field=canvas.getBoundingClientRect();aim(Math.atan2(dy*700/field.height,dx*1400/field.width))}
};
const release=()=>{const id=pointer;pointer=null;delete pad.dataset.engaged;pad.style.setProperty('--stick-x','0px');pad.style.setProperty('--stick-y','0px');if(id!==null&&pad.hasPointerCapture(id))pad.releasePointerCapture(id)};
pad.addEventListener('pointerdown',e=>{if(e.button!==0||pointer!==null||!active())return;e.preventDefault();pointer=e.pointerId;pad.dataset.engaged='true';pad.setPointerCapture(pointer);pad.focus({preventScroll:true});move(e)});
pad.addEventListener('pointermove',e=>{if(e.pointerId===pointer){e.preventDefault();move(e)}});
for(const event of ['pointerup','pointercancel','lostpointercapture'])pad.addEventListener(event,e=>{if(e.pointerId===pointer)release()});
pad.addEventListener('blur',release);
pad.addEventListener('keydown',e=>{if(!active())return;const directions={ArrowRight:0,ArrowDown:Math.PI/2,ArrowLeft:Math.PI,ArrowUp:-Math.PI/2};if(e.key in directions){e.preventDefault();aim(directions[e.key])}})
}
function trainingResult(){
const result=settleTraining(player,session);
if(!result)return;
save();
const kind=session.kind,name=GROUNDS.find(g=>g.id===kind).name;
modal(`<div class="training-rewards"><div class="reward">+${result.gain} ${name}</div><p class="training-xp">+${result.xp} XP · +${(result.statPoints||0)+result.levels*3} stat points · +${(result.skill||0)+result.levels} skill points</p><div class="row"><button class="secondary" data-finish="town">Back to Town</button><button class="primary" data-retry="${kind}">Train again</button></div></div>`)
}
function battleScreen(){
const layout=ARENA_BATTLE_ART;
return `<button class="gameplay-back" data-go="arena" aria-label="Back to Arena — pause battle"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 12H4m7-7-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg></button><div class="battle-heading"><div class="battle-title-plaque"><span class="battle-number">${session.survival?'Endless':'Battle '+session.stage}</span><h1 class="gameplay-place-title">Cloudring</h1></div><ol class="battle-monster-progress" id="battle-progress" aria-label="Monster progress">${[0,1,2].map(i=>`<li data-monster="${i}"${i===2?' class="monster-boss"':''}><span aria-hidden="true">${i===2?'<svg viewBox="0 0 24 24"><path d="M5 11a7 7 0 1 1 14 0v5l-3 1v4H8v-4l-3-1Z" fill="currentColor" stroke="#173745" stroke-width="1.5" stroke-linejoin="round"/><path d="M8 11h2m4 0h2m-4 3v2m-2 2v3m4-3v3" fill="none" stroke="#173745" stroke-width="2" stroke-linecap="round"/></svg>':''}</span></li>`).join('')}</ol></div>${levelProgress()}<div class="battle-hud" style="--hero-x:${layout.heroX/layout.width*100}%;--enemy-x:${layout.enemyX/layout.width*100}%;--combatant-y:${(layout.feetY+layout.offsetY)/layout.height*100}%"><div class="health hero-health-card"><h3 class="combatant-name">${escape(player.name)}</h3><div class="combatant-health-line"><div class="track"><i id="hero-health" style="width:100%"></i></div></div><div class="combatant-meta"><small id="hero-hp"></small><span class="combatant-status" id="hero-status" role="status"></span></div></div><div class="health enemy-health-card"><h3 class="combatant-name" id="enemy-name"></h3><div class="combatant-health-line"><div class="track"><i id="enemy-health" style="width:100%"></i></div><span class="boss-badge" id="enemy-boss" hidden>Boss</span></div><div class="combatant-meta"><small id="enemy-hp"></small><span class="combatant-status" id="enemy-status" role="status"></span></div></div></div><div class="battle-outcome" id="battle-outcome" role="status" aria-live="polite" hidden></div><button class="event" id="event" data-input="event" aria-label="Strike the opening" hidden>✦<br>STRIKE!</button><div class="controls battle-controls"><div class="cluster">${Object.entries(SKILLS).map(([k,s])=>`<button class="control" data-input="${k}" id="skill-${k}" ${player.skills.includes(k)?'':'disabled'}><span class="battle-skill-icon" aria-hidden="true">${s.icon}</span><span class="battle-skill-name">${s.name}</span><em>${player.skills.includes(k)?'Ready':'Locked'}</em></button>`).join('')}<button class="control gold" data-input="tonic" id="skill-tonic"><span class="battle-skill-icon" aria-hidden="true">❋</span><span class="battle-skill-name">Tonic</span><em>${player.potions} left</em></button></div></div>`
}
function updateBattleProgress(b){
const progress=$('#battle-progress'),key=b.wave+':'+b.won;if(progress.dataset.wave===key)return;
progress.dataset.wave=key;
const current=b.wave%3,start=b.survival?b.wave-current:0;
progress.setAttribute('aria-label',b.won?'All 3 monsters defeated':(b.survival?'Endless · ':'')+'Monster '+(b.wave+1)+(b.survival?'':' of 3'));
progress.style.setProperty('--monster-progress',String(current/2));
for(const marker of progress.children){const i=Number(marker.dataset.monster),active=i===current&&!b.won,cleared=i<current||b.won;marker.classList.toggle('is-current',active);marker.classList.toggle('is-cleared',cleared);marker.setAttribute('aria-label',(i===2?'Boss':'Monster '+(start+i+1))+(cleared?' defeated':active?' current':' upcoming'));if(active)marker.setAttribute('aria-current','step');else marker.removeAttribute('aria-current')}
}
function startBattle(stage,survival=false){if(mobile.applying){toast('Installing the update. Please wait.');return}if(!Number.isInteger(stage)||stage<1||stage>TOTAL_BATTLES||stage>player.stage||runInProgress())return;if(survival&&!player.survivalUnlocked)return;view='battle';session=new Battle(player,stage,sound,survival);paused=false;header('Cloudring');screen.innerHTML=battleScreen();updateHud()}
function bankBattleResult(b){
if(!b.result){const result=settleBattle(player,b,b.won);if(result){b.result=result;save();const progress=screen.querySelector('.town-progress');if(view==='battle'&&session===b&&progress)progress.outerHTML=levelProgress()}}
return b.result
}
function beginBattleOutcome(){
const b=session;if(view!=='battle'||!b?.done||b.resultShown)return;
bankBattleResult(b);
if(screen.classList.contains('battle-ending'))return;
screen.classList.add('battle-ending');
const outcome=$('#battle-outcome');outcome.hidden=false;outcome.dataset.result=b.won?'win':'lose';outcome.innerHTML=b.won?'<span>VICTORY</span>':'<span>DEFEAT</span>';
$('#event').hidden=true;
screen.querySelectorAll('[data-input]').forEach(button=>{button.disabled=true})
}
function battleRewardContent(b,result,retreated=false){
const rewards=[result.coins?['+'+gold(result.coins),'']:null,result.xp?['+'+result.xp,'XP']:null,(result.statPoints||0)+result.levels*3?['+'+((result.statPoints||0)+result.levels*3),'Stat points']:null,(result.skillPoints||0)+result.levels?['+'+((result.skillPoints||0)+result.levels),'Skill points']:null].filter(Boolean);
const notes=[result.levels?'Level '+player.level:'',b.won&&!b.survival&&b.stage===TOTAL_BATTLES?'Stage 3 coming soon':''].filter(Boolean);
return `<span class="eyebrow">${b.survival?b.wavesCleared+' waves':'Battle '+b.stage}</span><h2 class="battle-result-title">${b.won?'Victory':retreated?'Retreated':'Defeat'}</h2>${rewards.length?`<div class="battle-reward-grid">${rewards.map(([amount,label])=>`<div><strong>${amount}</strong><span>${label}</span></div>`).join('')}</div>`:''}${notes.length?`<p class="battle-result-note">${notes.join(' · ')}</p>`:''}<div class="row"><button class="secondary" data-finish="train">Train</button><button class="primary" data-finish="arena">Arena</button></div>`
}
function battleResult(retreated=false){
const b=session;if(!b||b.resultShown)return;
if(retreated&&!b.done)b.finish(false);
const result=bankBattleResult(b);if(!result)return;
b.resultShown=true;save();selectedStage=Math.min(player.stage,TOTAL_BATTLES);arenaPage=Math.floor((selectedStage-1)/BATTLES_PER_STAGE);
modal(battleRewardContent(b,result,retreated));dialog.classList.add('battle-result-dialog')
}
function pauseMenu(destination='town'){if(!runInProgress())return;paused=true;modal(`<span class="eyebrow">TAKE A BREATHER</span><h2>Adventure paused.</h2><p>${view==='training'?'Completed bars and missions earn rewards. Your unfinished stat bar is saved.':'You can resume here. Retreating ends this fight; survival rewards already earned are kept.'}</p><div class="row"><button class="secondary" data-leave="${destination}">${view==='training'?'Bank & leave':'Retreat'}</button><button class="primary" data-action="resume">Resume</button></div>`)}
function settings(){if(runInProgress())paused=true;modal(`<h2>Settings</h2><button class="secondary settings-control" data-action="sound" aria-pressed="${player.settings.sound}">Sound: ${player.settings.sound?'On':'Off'}</button><button class="secondary settings-control" data-action="motion" aria-pressed="${player.settings.motion}">Motion: ${player.settings.motion?'On':'Off'}</button><p id="offline-status" role="status">${mobile.status}</p><button id="check-update" class="secondary settings-control" data-action="check-update" ${mobile.checking?'disabled':''}>Check for updates</button><button id="install-update" class="secondary settings-control" data-action="app-update" ${mobile.updateReady?'':'hidden'} ${runInProgress()?'disabled':''}>${runInProgress()?'Finish your run to update':'Install game update'}</button><button class="secondary settings-control" data-action="test-menu" ${runInProgress()?'disabled':''}>Economy testing${testing?' · On':''}</button><small class="settings-version">Version 30${testing?' · Test save':''}</small>${saveWarning?'<p>Saving is currently unavailable.</p>':''}<button class="primary settings-control" data-action="close">Close</button>`)}
function testMenu(){if(runInProgress())return;modal(`<h2>Economy testing</h2><p>${testing?'Using a separate test save. Your real adventure is untouched.':'Jump to a battle and try the economy using a separate test save.'}</p>${testing?`<div class="test-fields"><label>Battle<select id="test-battle">${Array.from({length:TOTAL_BATTLES},(_,i)=>i+1).map(n=>`<option value="${n}" ${n===testBattle?'selected':''}>${n}${n%10===0?' · Boss':''}</option>`).join('')}</select></label><label>Preparation<select id="test-preparation">${TEST_PREPARATIONS.map(option=>`<option value="${option.id}" ${option.id===testPreparation?'selected':''}>${option.label}</option>`).join('')}</select></label></div><button class="primary settings-control" data-action="test-load">Load checkpoint</button><small class="test-note">Replaces only the test adventure. Presets are assumed loadouts, not simulated playthroughs.</small><button class="secondary settings-control" data-test-win="${selectedStage}">Award test victory · Battle ${selectedStage}</button><div class="test-idle-buttons" role="group" aria-label="Advance the test idle clock"><button class="secondary" data-test-idle="300000">+5 min</button><button class="secondary" data-test-idle="86400000">+24 hours</button><button class="secondary" data-test-idle="259200000">+72 hours</button></div><div class="test-actions"><button class="secondary" data-action="test-fresh">Fresh test hero</button><button class="secondary" data-action="test-exit">Return to real save</button></div>`:'<button class="primary settings-control" data-action="test-enter">Enter test mode</button>'}<button class="secondary settings-control" data-action="close">Close</button>`);dialog.classList.add('economy-test-dialog')}
function syncPlayerDestination(target){selectedStage=Math.min(player.stage,TOTAL_BATTLES);arenaPage=Math.floor((selectedStage-1)/BATTLES_PER_STAGE);rigState={pose:'standing',playing:true,animated:true,time:0,...player.equipment};closeModal();navigate(target,true)}
function changeTestMode(enabled){if(runInProgress())return;if(!save())return;testing=enabled;gameStorage=testing?testStorage(storage):storage;player=readSave(gameStorage).player;const url=new URL(location.href);if(testing)url.searchParams.set('test','1');else url.searchParams.delete('test');history.replaceState(null,'',url.pathname+url.search+url.hash);testBattle=Math.min(player.stage,TOTAL_BATTLES);syncPlayerDestination('town');if(testing)testMenu();else toast('Your real adventure is restored.')}
function loadTestCheckpoint(fresh=false){if(!testing||runInProgress())return;if(!fresh){testBattle=Number($('#test-battle').value);testPreparation=$('#test-preparation').value}player=fresh?freshPlayer():createTestCheckpoint(testBattle,testPreparation);if(fresh){player.name='Test Rook';testBattle=1;testPreparation='ready'}save();syncPlayerDestination(fresh?'town':'arena');toast(fresh?'Fresh test hero ready.':'Test checkpoint loaded · Battle '+testBattle)}
function appearance(){modal(`<h2>Appearance</h2><label for="hero-name">Hero name</label><input id="hero-name" maxlength="18" value="${escape(player.name)}" autocomplete="off"><label>Scarf color</label><div class="row">${[['#63dbc4','Sea glass'],['#f0ad65','Sunrise'],['#b89be0','Dusk']].map(([color,label])=>`<button class="secondary" data-scarf="${color}" style="border-color:${color};color:${color}" aria-pressed="${player.scarf===color}">${label}${player.scarf===color?' ✓':''}</button>`).join('')}</div><div class="row"><button class="primary" data-action="name-save">Save</button></div>`)}
function act(el){if(el.disabled)return;const d=el.dataset;if(d.testWin){const stage=Number(d.testWin);if(testing&&(!runInProgress())&&Number.isInteger(stage)&&stage>=1&&stage<=Math.min(player.stage,TOTAL_BATTLES)){const reward=settleBattle(player,{stage,survival:false,rewarded:false},true);save();syncPlayerDestination('forge');toast('Test victory · +'+formatCoins(reward.coins))}return}if(d.testIdle){if(testing&&(!runInProgress())&&advanceTestIdle(player,Number(d.testIdle))){save();syncPlayerDestination('legacy');toast('Test idle clock advanced.')}return}if(d.go){navigate(d.go);return}if(d.rigPose){if(rigPoses.some(([key])=>key===d.rigPose)){rigState.pose=d.rigPose;rigState.playing=d.rigPose==='standing'||d.rigPose==='attack'&&Boolean(FULL_BODY_ATTACK_ART[rigState.armor])||['airborne','landing'].includes(d.rigPose)&&Boolean(FULL_BODY_JUMP_ART[rigState.armor]);rigState.animated=rigState.playing;rigState.time=0;heroRigMenu();screen.querySelector(`[data-rig-pose="${rigState.pose}"]`).focus({preventScroll:true})}return}if(d.train){startTraining(d.train);return}if(d.arenaPage!==undefined){const page=Number(d.arenaPage);if(!Number.isInteger(page)||!CAMPAIGN_STAGES[page])return;arenaPage=page;const stage=CAMPAIGN_STAGES[page];if(!stage.comingSoon)selectedStage=Math.min(stage.lastBattle,Math.max(stage.firstBattle,player.stage));arenaMenu();screen.querySelector('.arena-page-title').focus({preventScroll:true});return}if(d.stage){const stage=Number(d.stage);if(!Number.isInteger(stage)||stage<1||stage>TOTAL_BATTLES||stage>player.stage)return;selectedStage=stage;arenaPage=Math.floor((stage-1)/BATTLES_PER_STAGE);arenaMenu();screen.querySelector(`[data-stage="${selectedStage}"]`).focus({preventScroll:true});return}if(d.fight){startBattle(Number(d.fight));return}if(d.survival){startBattle(Math.max(1,Math.min(player.stage-1,TOTAL_BATTLES)),true);return}if(d.input){if(session&&!paused){const changed=session.input(d.input);if(view==='battle'&&changed){if(d.input==='tonic')save();if(session.done)beginBattleOutcome()}}return}if(d.finish){closeModal();navigate(d.finish,true);return}if(d.retry){closeModal();session=null;startTraining(d.retry);return}if(d.leave){closeModal();if(view==='training')trainingResult();else battleResult(true);return}if(d.scarf){const name=$('#hero-name').value;player.scarf=d.scarf;appearance();$('#hero-name').value=name;return}let result;if(d.action==='armory-buy')result=buyArmory(player);if(d.item)result=buyItem(player,d.item);if(d.upgrade)result=upgradeGround(player,d.upgrade);if(d.skill)result=learnSkill(player,d.skill);if(d.legacy)result=upgradeLegacy(player,d.legacy);if(d.stat){const count=allocationCount==='all'?player.statPoints:Math.min(player.statPoints,Number(allocationCount));if(allocateStat(player,d.stat,count)){save();heroMenu()}return}if(result){if(result.ok){save();navigate(view,true);sound('heal')}toast(result.message);return}switch(d.action){case'check-update':mobile.checkForUpdates();break;case'test-menu':testMenu();break;case'test-enter':changeTestMode(true);break;case'test-exit':changeTestMode(false);break;case'test-load':loadTestCheckpoint();break;case'test-fresh':loadTestCheckpoint(true);break;case'rig-play':rigState.playing=!rigState.playing;rigState.animated=true;heroRigMenu();screen.querySelector('[data-action="rig-play"]').focus({preventScroll:true});break;case'app-update':if(!runInProgress()){save();mobile.applyUpdate().then(message=>{if(message)toast(message)})}break;case'pause':pauseMenu();break;case'resume':case'close':closeModal();break;case'sound':player.settings.sound=!player.settings.sound;save();sound('heal');settings();break;case'motion':player.settings.motion=!player.settings.motion;save();settings();break;case'appearance':appearance();break;case'name-save':player.name=$('#hero-name').value.trim().slice(0,18)||'Rook';save();closeModal();heroMenu();break;case'tonic-buy':result=purchasePotion(player);if(result.ok){save();forge()}toast(result.message);break;case'collect':{const amount=collectMuseum(player);save();legacy();toast(amount?'Collected '+formatCoins(amount)+'.':player.cleared.length?'Your gallery is still earning. Check back soon.':'Clear your first arena battle to start earning idle income.');break}}}
screen.addEventListener('change',e=>{if(e.target.matches('[data-stat-amount]')){if(['1','5','all'].includes(e.target.value)){allocationCount=e.target.value;heroMenu();screen.querySelector('[data-stat-amount]').focus({preventScroll:true})}return}if(!e.target.matches('[data-rig-set]'))return;const set=ARMORY_SETS.find(set=>set.id===e.target.value);if(!set)return;Object.assign(rigState,set.equipment,{time:0});heroRigMenu();screen.querySelector('[data-rig-set]').focus({preventScroll:true})});
document.addEventListener('pointerdown',e=>{const button=e.target.closest('button');if(!button||e.button!==0||button.id==='critical-playfield'&&e.isPrimary===false)return;e.preventDefault();if(button.id==='critical-playfield')button.dataset.pointerFocus='';button.focus({preventScroll:true});if(button.id==='settings')settings();else act(button)});
document.addEventListener('click',e=>{if(e.detail!==0)return;const button=e.target.closest('button');if(!button)return;if(button.id==='settings')settings();else act(button)});
document.addEventListener('keydown',e=>{const field=$('#critical-playfield');if(field)delete field.dataset.pointerFocus;if(e.target===field&&e.repeat&&(e.key==='Enter'||e.key===' '))e.preventDefault()});
document.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('gesturestart',e=>e.preventDefault(),{passive:false});document.addEventListener('touchstart',e=>{if(e.touches.length>1)e.preventDefault()},{passive:false});
dialog.addEventListener('cancel',e=>{e.preventDefault();if(session?.done&&(view!=='battle'||session.resultShown)){closeModal();navigate(view==='training'?'train':'arena',true)}else closeModal()});
function syncViewport(){document.documentElement.style.setProperty('--app-height',(window.visualViewport?.height||window.innerHeight)+'px');if(session?.streak)placeStrengthControls(screen);placeTownTargets();if(window.innerHeight>window.innerWidth&&session&&!session.done&&!paused)pauseMenu()}
window.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('resize',syncViewport);document.addEventListener('visibilitychange',()=>{if(document.hidden&&session&&!session.done&&!paused)pauseMenu();if(view==='training'&&session&&!session.rewarded){checkpointTraining(player,session);save()}lastTime=0});window.addEventListener('pagehide',()=>{if(view==='training'&&session&&!session.rewarded)settleTraining(player,session);if(view==='battle'&&session){if(session.done)bankBattleResult(session);else if(session.survival&&!session.rewarded)settleBattle(player,session,false);}save()});window.addEventListener('pageshow',e=>{if(e.persisted){player=readSave(gameStorage).player;if(dialog.open)dialog.close();navigate('town',true)}});
function setText(id,value){const el=document.getElementById(id);if(el&&el.textContent!==String(value))el.textContent=value}
function updateHud(){if(view==='training'){for(const [part,delay] of [['goal',0],['mission',.2],['controls',.35]])screen.style.setProperty('--intro-'+part,session.entrance(delay));setText('time',Math.max(0,Math.ceil(60-session.elapsed)));setText('hits',session.hits);if(session.kind==='accuracy'){setText('accuracy-points',Math.floor(session.goalProgress)+' / '+session.goalTarget);const meter=$('#accuracy-meter');meter.max=session.goalTarget;meter.value=session.goalProgress;const mission=trainingMission('accuracy',session.missionNumber);setText('accuracy-mission',mission.title+' · '+Math.floor(session.missionProgress)+'/'+mission.target)}setText('combo',session.streak?'×'+session.combo:session.combo+'×');if(session.kind==='crit')setText('critical-cue-status',session.criticalRound?.phase==='fake'?'Fake cue. Wait.':['ready','finish'].includes(session.criticalRound?.phase)?'Hit now.':'');const combo=$('#combo'),cue=session.comboFeedback>0;combo.style.setProperty('--combo-scale',session.motion?1+(session.comboStar?.35:.22)*Math.sin(Math.PI*(1-session.comboFeedback/.42)):1);combo.classList.toggle('combo-success',cue);combo.classList.toggle('combo-star',cue&&session.comboStar);if(session.streak){const meter=$('#goal-meter');if(meter.max!==session.goalTarget)meter.max=session.goalTarget;if(meter.value!==session.goalProgress)meter.value=session.goalProgress;const track=meter.closest('.goal-track'),fillWidth=(session.goalFeedback>1.56?100:Math.max(0,Math.min(100,session.goalProgress/session.goalTarget*100)))+'%';if(track.style.getPropertyValue('--goal-progress')!==fillWidth)track.style.setProperty('--goal-progress',fillWidth);meter.setAttribute('aria-valuetext',Number(session.goalProgress.toFixed(2))+' of '+session.goalTarget+' points');meter.closest('.training-goal').classList.toggle('goal-banked',session.goalFeedback>0);if(session.goals)setText('goal-announcement',session.goals+' goals banked. Next goal: '+session.goalTarget+' points.');const mission=trainingMission(session.kind,session.missionNumber);setText('mission-number','Mission #'+mission.number);setText('mission-title',mission.title);setText('mission-progress',(mission.type==='unhurt'?session.missionProgress.toFixed(1):session.missionProgress)+' / '+mission.target);const missionMeter=$('#mission-meter');missionMeter.max=mission.target;missionMeter.value=session.missionProgress;missionMeter.parentElement.classList.toggle('goal-banked',session.missionFeedback>0);setText('mission-message',session.missionFeedback>0?session.missionMessage:'');const tutorial=$('#strength-tutorial');if(tutorial){if(session.tutorialRemaining<=0)tutorial.remove();else tutorial.style.opacity=Math.min(1,session.tutorialRemaining/.5)}}if(session.kind==='dodge')document.querySelectorAll('[data-input]').forEach(b=>b.classList.toggle('gold',b.dataset.input===session.action&&session.elapsed-session.dodgeAt<DODGE_TIMING.window))}else if(view==='battle'){const b=session;$('#hero-health').style.width=pct(b.hp/b.stats.hp);$('#enemy-health').style.width=pct(b.enemyHp/b.foe.hp);setText('hero-hp',b.hp+' / '+b.stats.hp+' HP');setText('enemy-hp',b.enemyHp+' / '+b.foe.hp+' HP');setText('enemy-name',b.foe.name);updateBattleProgress(b);$('#enemy-boss').hidden=b.wave%3!==2;setText('hero-status',b.ward>0?'Guarded':'');setText('enemy-status',[b.stunTurns>0?'Stunned':'',b.poison?'Poisoned':''].filter(Boolean).join(' · '));$('#event').hidden=b.event<=0||b.done;for(const k of [...Object.keys(SKILLS),'tonic']){const el=$('#skill-'+k);const learned=k==='tonic'?player.potions>0:player.skills.includes(k);el.disabled=b.done||!learned||b.cooldowns[k]>0||(k==='tonic'&&b.tonicUses>=2)||((k==='mend'||k==='tonic')&&b.hp>=b.stats.hp);el.querySelector('em').textContent=b.done?'Finished':!learned?(k==='tonic'?'Empty':'Locked'):k==='tonic'&&b.tonicUses>=2?'Used 2/2':b.cooldowns[k]>0?Math.ceil(b.cooldowns[k])+'s':k==='tonic'?Math.min(player.potions,2-b.tonicUses)+' uses':'Ready'}}}
function drawEquipmentIllustrations(){screen.querySelectorAll('canvas[data-illustration]').forEach(c=>{const id=c.dataset.illustration;if(!ITEMS[id])return;const q=c.getContext('2d');q.clearRect(0,0,c.width,c.height);if(!equipmentIllustration(q,c.width,c.height,id))menuIllustration(q,c.width,c.height,id)})}
function drawPortraits(t){document.querySelectorAll('canvas[data-hero]').forEach(c=>{const q=c.getContext('2d');q.clearRect(0,0,c.width,c.height);if(hasRigEquipment(player.equipment)&&rigPortrait(q,c.width,c.height,player.equipment,t,{motion:player.settings.motion&&!rigMotion.matches}))return;if(c.dataset.hero==='idle'&&['forge','hero'].includes(view)&&idlePortrait(q,c.width,c.height,player.equipment,t))return;hero(q,c.width/2,c.height-15,1.8,player.equipment,t,0,0,player.scarf)});document.querySelectorAll('canvas[data-enemy]').forEach(c=>{const q=c.getContext('2d');q.clearRect(0,0,c.width,c.height);enemy(q,c.width/2,c.height-15,Number(c.dataset.scale)||1.3,Number(c.dataset.enemy),t)})}
function drawRigPreview(dt){const c=screen.querySelector('canvas[data-rig-preview]');if(!c)return;const motion=player.settings.motion&&!rigMotion.matches;if(rigState.playing&&motion&&!dialog.open&&window.innerWidth>=window.innerHeight)rigState.time+=dt;const q=c.getContext('2d');q.clearRect(0,0,c.width,c.height);const ready=rigPreview(q,c.width,c.height,rigState,rigState.time,{pose:rigState.pose,playing:rigState.playing,animated:rigState.animated,motion});const status=screen.querySelector('[data-rig-state]'),message=ready?'':'Loading…';if(status.textContent!==message)status.textContent=message;const play=screen.querySelector('[data-action="rig-play"]');play.disabled=!motion;play.setAttribute('aria-label',motion?(rigState.playing?'Pause animation':'Play animation'):'Animation disabled by motion preference')}
function drawTownHero(c,x,y,scale,equipment,time){townHero(c,x,y,scale,equipment,time,{motion:player.settings.motion&&!rigMotion.matches})}
function frame(timestamp){requestAnimationFrame(frame);const dt=lastTime?Math.min((timestamp-lastTime)/1000,.05):0;lastTime=timestamp;if(session?.savePending){checkpointTraining(player,session);save()}if(view==='battle'&&session?.done&&!session.resultShown&&!dialog.open)paused=document.hidden||window.innerHeight>window.innerWidth;if(document.hidden)return;if(view==='battle'&&session?.done)beginBattleOutcome();if(session&&!paused&&!dialog.open&&window.innerWidth>=window.innerHeight){if(!session.done)session.step(dt);if(session.done){if(view==='training')trainingResult();else if(!session.resultShown){beginBattleOutcome();session.advanceOutcome(dt);if(session.outcomeElapsed>=session.outcomeDuration)battleResult()}}}const r=canvas.getBoundingClientRect(),d=Math.min(window.devicePixelRatio||1,3);if(!r.width||!r.height)return;if(canvas.width!==Math.round(r.width*d)||canvas.height!==Math.round(r.height*d)){canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d)}ctx.setTransform(d,0,0,d,0,0);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';const t=player.settings.motion?timestamp/1000:0;drawWorld(ctx,r.width,r.height,t,view==='town'||view==='home'||view==='arena'?view:view==='battle'?'battle':'training',player.equipment,drawTownHero);if(session){ctx.save();ctx.scale(r.width/1400,r.height/700);if((view==='training'?session.motion:player.settings.motion)&&!paused&&session.hit&&session.kind!=='block')ctx.translate(Math.sin(timestamp*.08)*session.hit*5,0);session.draw(ctx,view==='training'?(session.motion?session.elapsed:0):paused?0:t);ctx.restore();updateHud()}drawPortraits(t);if(view==='forge')drawEquipmentIllustrations();if(view==='hero-rig')drawRigPreview(dt);if(view==='legacy')updateCollectButton()}
function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();const tools=[{name:'read_adventure',title:'Read adventure progress',description:'Read this device’s saved hero progression and current game screen.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments accepted.');return{screen:view,hero:player.name,level:player.level,coins:player.coins.toString(),testMode:testing,stats:{...player.stats},equipment:{...player.equipment},cleared:[...player.cleared],skillPoints:player.skillPoints,statPoints:player.statPoints}}},{name:'navigate_adventure',title:'Open game destination',description:'Navigate to a town destination. Does not play, buy, spend points or grant rewards. Refuses during an active round.',inputSchema:{type:'object',properties:{destination:{type:'string',enum:['town','home','train','arena','forge','hero','legacy']}},required:['destination'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).length!==1||!['town','home','train','arena','forge','hero','legacy'].includes(input.destination))throw Error('Invalid destination.');if(runInProgress()||dialog.open)throw Error('Finish the active round or dialog first.');navigate(input.destination);return{screen:view}}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
syncViewport();navigate('town');if(loaded.warning)toast(loaded.warning);requestAnimationFrame(frame);registerAgentTools();
